package review.dual;
import review.mysql.*;
import org.junit.jupiter.api.*;
import java.util.*;
import java.sql.*;
import java.nio.file.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class DualLedgerAdminTests {
 java.lang.reflect.Method method;Connection c;PreparedStatement alter;List<String> done;DualLedgerServer.Scope s;Object connector;String opened;
 @BeforeEach void setup()throws Exception{String id=UUID.randomUUID().toString();var a=new com.fasterxml.jackson.databind.ObjectMapper().valueToTree(Map.of("instanceDirectory",Path.of("build/synthetic-instance").toAbsolutePath().toString(),"trustStore",Path.of("build/synthetic-public-ca.p12").toAbsolutePath().toString()));s=new DualLedgerServer.Scope(Path.of("build/synthetic-dual"),id,id,"SCENARIO","a".repeat(64),a);done=new ArrayList<>();c=mock(Connection.class);alter=mock(PreparedStatement.class);when(c.prepareStatement("ALTER USER 'root'@'localhost' IDENTIFIED BY ?")).thenReturn(alter);Class<?> type=Class.forName("review.mysql.MySqlInstanceAdmin$Connector");connector=java.lang.reflect.Proxy.newProxyInstance(type.getClassLoader(),new Class[]{type},(p,m,args)->{opened=(String)args[0];return c;});method=DualLedgerAdmin.class.getDeclaredMethod("provision",DualLedgerServer.Scope.class,String.class,String.class,String.class,String.class,type,List.class);method.setAccessible(true);}
 Throwable runFailure()throws Exception{try{method.invoke(null,s,"synthetic-store-only","synthetic-initial-only","synthetic-next-password-only","synthetic-app-password-only",connector,done);throw new AssertionError("Expected safe failure");}catch(java.lang.reflect.InvocationTargetException e){return e.getCause();}}
 @Test void expiredRootChangeIsFirstSqlAndNo3306Fallback()throws Exception{when(alter.execute()).thenThrow(new SQLException("synthetic secret must never escape","HY000",1820));Throwable e=runFailure();assertEquals(List.of("NEW_ROOT_TLS"),done);assertFalse(e.toString().contains("synthetic secret"));verify(c).prepareStatement("ALTER USER 'root'@'localhost' IDENTIFIED BY ?");verify(c,never()).createStatement();assertTrue(opened.contains("127.0.0.1:3307/"));assertTrue(opened.contains("VERIFY_IDENTITY"));assertTrue(opened.contains("disconnectOnExpiredPasswords=false"));}
 @Test void rootSuccessThenIdentityFailureNeverExecutesDdl()throws Exception{var st=mock(Statement.class);var rows=mock(ResultSet.class);when(c.createStatement()).thenReturn(st);when(st.executeQuery("SELECT @@port,@@datadir")).thenReturn(rows);when(rows.next()).thenReturn(true);when(rows.getInt(1)).thenReturn(3306);Throwable e=runFailure();assertEquals(List.of("NEW_ROOT_TLS","NEW_ROOT_PASSWORD"),done);var order=inOrder(c,alter,st);order.verify(c).prepareStatement("ALTER USER 'root'@'localhost' IDENTIFIED BY ?");order.verify(alter).setString(eq(1),anyString());order.verify(alter).execute();order.verify(alter).close();order.verify(c).createStatement();order.verify(st).executeQuery("SELECT @@port,@@datadir");verify(st,never()).execute(anyString());assertFalse(e.toString().contains("synthetic-next"));}
 @Test void connectionFailureCannotAlterOrPublishEvidence()throws Exception{Class<?> type=Class.forName("review.mysql.MySqlInstanceAdmin$Connector");connector=java.lang.reflect.Proxy.newProxyInstance(type.getClassLoader(),new Class[]{type},(p,m,args)->{throw new SQLException("synthetic credential","28000",1045);});Throwable e=runFailure();assertTrue(done.isEmpty());assertFalse(e.toString().contains("synthetic credential"));verifyNoInteractions(c);}
 @Test void exclusiveProvisionClaimRejectsReuseWithoutChangingEvidence(@org.junit.jupiter.api.io.TempDir Path dir)throws Exception{var local=new DualLedgerServer.Scope(dir,s.id(),s.schemaId(),s.phase(),s.hash(),s.approval());DualLedgerAdmin.claimProvision(local);byte[] before=Files.readAllBytes(dir.resolve("admin-process-claim.json"));assertThrows(Exception.class,()->DualLedgerAdmin.claimProvision(local));assertArrayEquals(before,Files.readAllBytes(dir.resolve("admin-process-claim.json")));assertFalse(Files.exists(dir.resolve("phase-failure-provision.json")));Path completed=Files.createDirectory(dir.resolve("completed"));Files.writeString(completed.resolve("provisioned.json"),"{}");assertThrows(Exception.class,()->DualLedgerAdmin.claimProvision(new DualLedgerServer.Scope(completed,s.id(),s.schemaId(),s.phase(),s.hash(),s.approval())));assertFalse(Files.exists(completed.resolve("admin-process-claim.json")));}
}
